mutation CreateContact($firstName: String!, $lastName: String!, $email: String!, $userId: ID) {
  createContact(firstName: $firstName, lastName: $lastName, email: $email, userId: $userId) {
    id
    type
    status
    insertedAt
    updatedAt
    name
    email
    contactInfo {
      kind
      source
      value
    }
    integrationReferences {
      crmUrl
      recordId
      recordType
      service
    }
  }
}
